#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
# Every ENV_FILE path below is relative to the repo root, so anchor there
# regardless of where this script was invoked from.
cd "$(dirname "${BASH_SOURCE[0]}")/../../.." || exit 1

# Every stage waits on `read`. Without a real terminal those reads hit EOF
# immediately, so the wizard would run all six stages in one breath and write
# empty values over the env files. Refuse instead.
if [[ ! -t 0 ]]; then
  printf '\n  This wizard needs an interactive terminal: stdin is not a TTY, so every\n'
  printf '  prompt would read EOF and the env files would end up empty.\n\n'
  printf '  Open a normal terminal window and run:\n'
  printf '    bash %s\n\n' "${BASH_SOURCE[0]}"
  exit 1
fi

ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key ($ENV_FILE)")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — skinsense-v2 ticket 01: provision Google OAuth + Supabase
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
PKG_NAME="com.dinh144.skinsense"          # apps/mobile/app.json expo.android.package
GUESSED_VERCEL_DOMAIN="skinsense-v2.vercel.app"

banner "skinsense-v2: Supabase + Google OAuth provisioning (ticket 01)"

# ── Stage 1: Supabase project ──────────────────────────────────────────────
stage "Supabase: create project"
say "This project backs both apps/web and apps/mobile."
open_url "https://supabase.com/dashboard/new"
step "Pick your org, name it e.g. 'skinsense-v2', choose a region, set a DB password (not needed elsewhere — a password manager is fine)."
pause "Wait for provisioning to finish, then press Enter."
step "Go to Project Settings → API."
ENV_FILE="apps/web/.env.local"
ask NEXT_PUBLIC_SUPABASE_URL "Project URL (https://<ref>.supabase.co):"
ask NEXT_PUBLIC_SUPABASE_ANON_KEY "anon public key:"
ask_secret SUPABASE_SERVICE_ROLE_KEY "service_role key (kept secret, click Reveal):"
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
note "service_role key is only for reference here — Supabase Edge Functions get it injected automatically at runtime, ticket 03 shouldn't need to pass it around."
ENV_FILE="apps/mobile/.env"
write_env EXPO_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env EXPO_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"
PROJECT_REF="${NEXT_PUBLIC_SUPABASE_URL#https://}"
PROJECT_REF="${PROJECT_REF%%.*}"
note "Project ref detected: $PROJECT_REF (used to jump straight to pages in later stages)."

# ── Stage 2: Storage bucket ─────────────────────────────────────────────────
stage "Supabase: private 'photos' bucket"
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/storage/buckets"
step "New bucket → name exactly 'photos' → leave 'Public bucket' OFF."
step "Create the bucket."
confirm "Bucket 'photos' created and private?" || warn "come back and finish this before ticket 03/07/08 need it"

# ── Stage 3: Google OAuth consent screen ────────────────────────────────────
stage "Google Cloud: OAuth consent screen"
open_url "https://console.cloud.google.com/projectcreate"
step "Create (or select) a Google Cloud project, e.g. 'skinsense-v2'."
open_url "https://console.cloud.google.com/auth/branding"
step "Google Auth Platform → Branding: fill App name + user support email, then Audience → User type: External."
step "App name: SkinSense (or your choice), user support email: your email."
step "Data Access → Add or remove scopes: 'email' and 'profile' only — nothing else (avoids Google's verification review and the 100-user/7-day Testing-mode caps)."
warn "if the form asks for a Privacy Policy URL and won't let you skip it: the privacy page doesn't exist yet (that's ticket 11). Try leaving it blank first — non-sensitive scopes usually don't require one — and only if it blocks you, put a placeholder and revisit when ticket 11 ships."
step "Audience → Publish app: status must say 'In production', not 'Testing'."
confirm "Consent screen published to Production with only email+profile scopes?" || warn "come back and finish this before any sign-in will work"

# ── Stage 4: Web OAuth client ID ────────────────────────────────────────────
stage "Google Cloud: Web OAuth client ID"
open_url "https://console.cloud.google.com/auth/clients"
step "Clients → Create client → Application type: Web application."
step "Name: e.g. 'skinsense-v2 web'."
step "Authorized JavaScript origins → add: http://localhost:3000"
step "Authorized JavaScript origins → also add: https://${GUESSED_VERCEL_DOMAIN}"
note "that Vercel domain is a guess from the repo name (package.json 'skinsense-v2') — the project isn't deployed yet. If the real Vercel domain ends up different, come back and add it here."
step "No redirect URIs needed — this is the ID-token flow, not redirect OAuth."
step "Create. The client secret is shown ONCE, in the dialog that appears — copy both now; afterwards the console only shows its last 4 characters."
ENV_FILE="apps/web/.env.local"
ask NEXT_PUBLIC_GOOGLE_WEB_CLIENT_ID "Web OAuth Client ID (ends .apps.googleusercontent.com):"
ask_secret GOOGLE_WEB_CLIENT_SECRET "Web OAuth Client secret (kept secret — Supabase's provider form may ask for it):"
write_env NEXT_PUBLIC_GOOGLE_WEB_CLIENT_ID "$NEXT_PUBLIC_GOOGLE_WEB_CLIENT_ID"
write_env GOOGLE_WEB_CLIENT_SECRET "$GOOGLE_WEB_CLIENT_SECRET"
ENV_FILE="apps/mobile/.env"
write_env EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID "$NEXT_PUBLIC_GOOGLE_WEB_CLIENT_ID"
note "mobile uses this same Web client ID as the 'webClientId' param to @react-native-google-signin/google-signin, per docs/research/auth-google-idtoken.md."

# ── Stage 5: Android OAuth client ID ────────────────────────────────────────
stage "Google Cloud: Android OAuth client ID"
say "This needs a SHA-1 from the EAS build keystore, which only exists after the first EAS build."
if confirm "Do this stage now? Answer n if the first EAS build has not run yet — it is ticket 01b."; then
  say "Package name (from apps/mobile/app.json): $PKG_NAME"

  DEBUG_KEYSTORE="$HOME/.android/debug.keystore"
  if [[ ! -f "$DEBUG_KEYSTORE" ]]; then
    step "No debug keystore found at $DEBUG_KEYSTORE — generating the standard Android debug one."
    mkdir -p "$HOME/.android"
    keytool -genkey -v -keystore "$DEBUG_KEYSTORE" -storepass android -alias androiddebugkey \
      -keypass android -keyalg RSA -keysize 2048 -validity 10000 \
      -dname "CN=Android Debug,O=Android,C=US" >/dev/null
  fi
  DEBUG_SHA1=$(keytool -list -v -keystore "$DEBUG_KEYSTORE" -alias androiddebugkey -storepass android -keypass android 2>/dev/null \
    | grep -m1 -oE '([0-9A-Fa-f]{2}:){19}[0-9A-Fa-f]{2}')
  say "Debug keystore SHA-1: $DEBUG_SHA1"

  step "Now the EAS keystore. Make sure you're logged in: run 'eas login' in another terminal if needed."
  pause "Logged in to EAS? Press Enter to continue."
  step "Run: eas credentials"
  step "Pick Android → this project → Keystore: Manage everything needed to build your project → view or create a keystore, then copy its SHA-1 fingerprint."
  ask EAS_SHA1 "EAS keystore SHA-1 (paste from the eas credentials output):"

  step "Back in Google Cloud: Clients → Create client → Application type: Android."
  step "Package name: $PKG_NAME  |  SHA-1: $DEBUG_SHA1"
  note "check whether this form lets you add a second SHA-1 fingerprint to the same client (newer Console UIs do). If not, create a SECOND Android OAuth client ID, same package name, SHA-1: $EAS_SHA1"
  ask GOOGLE_ANDROID_CLIENT_ID "Android OAuth Client ID (debug, or combined):"
  ask GOOGLE_ANDROID_CLIENT_ID_RELEASE "Second Android OAuth Client ID for the EAS SHA-1 (leave blank if you added both SHA-1s to one client):"
  ENV_FILE="apps/mobile/.env"
  write_env EXPO_PUBLIC_GOOGLE_ANDROID_CLIENT_ID "$GOOGLE_ANDROID_CLIENT_ID"
  [[ -n "$GOOGLE_ANDROID_CLIENT_ID_RELEASE" ]] && write_env EXPO_PUBLIC_GOOGLE_ANDROID_CLIENT_ID_RELEASE "$GOOGLE_ANDROID_CLIENT_ID_RELEASE"
else
  note "skipped — finish it from ticket 01b after the first EAS build. Stage 6 then has no Android client ID to add yet; come back to that field too."
fi

# ── Stage 6: Wire Supabase Auth Google provider ─────────────────────────────
stage "Supabase: enable Google provider"
open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/providers"
step "Find Google in the provider list, toggle it on."
step "Client ID: paste the Web OAuth Client ID ($NEXT_PUBLIC_GOOGLE_WEB_CLIENT_ID)."
step "Client secret: paste the Web OAuth Client secret you saved in stage 4."
step "Authorized Client IDs (extra IDs Supabase should accept tokens from): add the Android client ID(s) from stage 5."
note "if native sign-in fails with a nonce error later, revisit 'Skip nonce check' here — flagged as unverified in docs/research/auth-google-idtoken.md."
confirm "Google provider enabled in Supabase with the Web + Android client IDs added?" || warn "come back and finish this before ticket 03 can wire auth"

finish
say "Ticket 01a done. Next unblocked: ticket 03 (auth wiring + session + schema tooling) can start once this is all confirmed."
